import React from 'react';
import { Card, CardContent } from '../ui/card';
import { Avatar, AvatarFallback } from '../ui/avatar';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { Mail, Phone, MapPin, FileText } from 'lucide-react';
import { Plus } from 'lucide-react';
import { useState } from 'react';
import { useAuth } from "../../contexts/AuthContext";
import { AssignConsultantModal } from '../modals/AssignConsultantModal';


export const ClientCard = ({ client, onContact, onViewProjects,onViewEquipo }) => {
    const { user } = useAuth();
    // Definir permisos por rol
  const isSuperAdmin = user?.role === "super_admin";
  const isAdmin = user?.role === "admin";
  const isUser = user?.role === "user";
   const { refetch } =
      useDashboardData();
    const [showConsultantModal, setShowConsultantModal] = useState(false);
    const canAssignedConsultant = isSuperAdmin || isAdmin || isUser;
      const handleModalSuccess = () => {
    refetch();
  };
  return (
    <Card>
      <CardContent className="p-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-4">
            <Avatar className="h-12 w-12">
              <AvatarFallback className="bg-green-100 text-green-700 text-lg">
                {client.company_name.substring(0, 2).toUpperCase()}
              </AvatarFallback>
            </Avatar>
            <div>
              <h3 className="text-lg font-semibold text-gray-900">{client.company_name}</h3>
              <p className="text-sm text-gray-600">{client.contact_person}</p>
              <p className="text-sm text-gray-500 capitalize">{client.industry}</p>
            </div>
          </div>
          <div className="text-right">
            <Badge className={client.status === 'active' ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'}>
              {client.status === 'active' ? 'Activo' : 'Inactivo'}
            </Badge>
            <div className="mt-2 space-x-2">
              <Button variant="outline" size="sm" onClick={() => onContact?.(client)}>
                <Mail className="w-4 h-4 mr-2" />
                Contactar
              </Button>
              <Button variant="outline" size="sm" onClick={() => onViewProjects?.(client)}>
                <FileText className="w-4 h-4 mr-2" />
                Proyectos
              </Button>
             {canAssignedConsultant && (
                <Button
                  onClick={() => setShowConsultantModal(true)}
                  variant="outline"
                  size="sm"
                >
                  <Plus className="w-4 h-4 mr-2" />
                  Equipo
                </Button>
              )}
            </div>
          </div>
        </div>
        
        <div className="mt-4 grid grid-cols-2 gap-4 text-sm text-gray-600">
          <div>
            <p className="flex items-center">
              <Mail className="w-4 h-4 mr-2" />
              {client.email}
            </p>
            <p className="flex items-center mt-1">
              <Phone className="w-4 h-4 mr-2" />
              {client.phone}
            </p>
          </div>
          <div>
            <p className="flex items-center">
              <MapPin className="w-4 h-4 mr-2" />
              {client.address}
            </p>
          </div>
        </div>
      </CardContent>
       {canAssignedConsultant && (
              <AssignConsultantModal
                isOpen={showConsultantModal}
                onClose={() => setShowConsultantModal(false)}
                onSuccess={handleModalSuccess}
              />
            )}
    </Card>
    
  );
};
